/**
 * @file src/lib/storageSortUtils.ts
 * Pure helpers for storage sort buttons and multi-criteria sorting.
 */

export const STORAGE_SORT_KEYS = [
  'pokedex',
  'level',
  'rarity',
  'hp',
  'attack',
  'spattack',
  'defense',
  'spdefense',
  'speed',
  'total',
  'shards',
  'shiny',
] as const;

export type StorageSortKey = (typeof STORAGE_SORT_KEYS)[number];
export type StorageSortOrder = 'asc' | 'desc';

export const STORAGE_SORT_I18N_KEYS: Record<StorageSortKey, string> = {
  pokedex: 'storage.sortPokedex',
  level: 'storage.sortLevel',
  rarity: 'storage.sortRarity',
  hp: 'storage.sortHp',
  attack: 'storage.sortAttack',
  spattack: 'storage.sortSpAttack',
  defense: 'storage.sortDefense',
  spdefense: 'storage.sortSpDefense',
  speed: 'storage.sortSpeed',
  total: 'storage.sortTotal',
  shards: 'storage.sortShards',
  shiny: 'storage.sortShiny',
};

export type StorageSortEntry = {
  key: StorageSortKey;
  order: StorageSortOrder;
};

export interface StorageSortCreature {
  name: string;
  type: string;
  level: number;
  rarity: string;
  maxHp: number;
  attack: number;
  spattack: number;
  defense: number;
  spdefense: number;
  speed: number;
  isShiny?: boolean;
}

export interface StorageSortContext {
  shards: Record<string, number>;
  pokemonSpriteIds: Record<string, number>;
  getCreatureCombatPower: (creature: StorageSortCreature) => number;
  getShardKey: (name: string, rarity: string) => string;
  useBaseStats?: boolean;
  getSpeciesRawBaseStats?: (name: string) => {
    hp: number;
    attack: number;
    spattack: number;
    defense: number;
    spdefense: number;
    speed: number;
  };
  getSpeciesBaseCombatPower?: (name: string) => number;
}

const RARITY_ORDER: Record<string, number> = {
  common: 1,
  rare: 2,
  epic: 3,
  legendary: 4,
};

export function isStorageSortKey(key: string): key is StorageSortKey {
  return (STORAGE_SORT_KEYS as readonly string[]).includes(key);
}

export function getDefaultStorageSortOrder(key: StorageSortKey): StorageSortOrder {
  return key === 'pokedex' ? 'asc' : 'desc';
}

export function toggleStorageSortStack(
  stack: StorageSortEntry[],
  key: StorageSortKey,
): StorageSortEntry[] {
  const idx = stack.findIndex((entry) => entry.key === key);
  if (idx === -1) {
    return [...stack, { key, order: getDefaultStorageSortOrder(key) }];
  }
  const entry = stack[idx];
  if (!entry) {
    return [...stack, { key, order: getDefaultStorageSortOrder(key) }];
  }
  const defaultOrder = getDefaultStorageSortOrder(key);
  if (entry.order === defaultOrder) {
    const next = stack.slice();
    next[idx] = { key, order: defaultOrder === 'asc' ? 'desc' : 'asc' };
    return next;
  }
  return stack.filter((_, i) => i !== idx);
}

export function normalizeStorageSortStack(raw: unknown): StorageSortEntry[] {
  if (!Array.isArray(raw)) return [];
  const result: StorageSortEntry[] = [];
  for (const item of raw) {
    if (!item || typeof item !== 'object') continue;
    const key = (item as { key?: unknown }).key;
    const order = (item as { order?: unknown }).order;
    if (typeof key !== 'string' || !isStorageSortKey(key)) continue;
    result.push({
      key,
      order: order === 'asc' ? 'asc' : 'desc',
    });
  }
  return result;
}

export function migrateStorageSortStack(
  sortBy: string | undefined,
  sortOrder: string | undefined,
  storageSortStack: unknown,
): StorageSortEntry[] {
  const normalized = normalizeStorageSortStack(storageSortStack);
  if (normalized.length > 0) return normalized;
  if (sortBy && sortBy !== 'none' && isStorageSortKey(sortBy)) {
    return [{ key: sortBy, order: sortOrder === 'asc' ? 'asc' : 'desc' }];
  }
  return [];
}

export function syncLegacyStorageSortFields(
  stack: StorageSortEntry[],
): { sortBy: string; sortOrder: StorageSortOrder } {
  const first = stack[0];
  return {
    sortBy: first?.key ?? 'none',
    sortOrder: first?.order ?? 'desc',
  };
}

export function storageSortStacksEqual(
  a: StorageSortEntry[],
  b: StorageSortEntry[],
): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const left = a[i];
    const right = b[i];
    if (!left || !right) return false;
    if (left.key !== right.key || left.order !== right.order) return false;
  }
  return true;
}

function compareValues(
  valueA: string | number,
  valueB: string | number,
  order: StorageSortOrder,
): number {
  if (typeof valueA === 'string' && typeof valueB === 'string') {
    return order === 'asc'
      ? valueA.localeCompare(valueB)
      : valueB.localeCompare(valueA);
  }
  const numA = Number(valueA);
  const numB = Number(valueB);
  return order === 'asc' ? numA - numB : numB - numA;
}

export function compareStorageCreatures(
  a: StorageSortCreature,
  b: StorageSortCreature,
  key: StorageSortKey,
  order: StorageSortOrder,
  ctx: StorageSortContext,
): number {
  let valueA: string | number = 0;
  let valueB: string | number = 0;

  switch (key) {
    case 'pokedex':
      valueA = ctx.pokemonSpriteIds[a.name] ?? 9999;
      valueB = ctx.pokemonSpriteIds[b.name] ?? 9999;
      break;
    case 'level':
      valueA = a.level;
      valueB = b.level;
      break;
    case 'rarity':
      valueA = RARITY_ORDER[a.rarity] ?? 0;
      valueB = RARITY_ORDER[b.rarity] ?? 0;
      break;
    case 'hp':
    case 'attack':
    case 'spattack':
    case 'defense':
    case 'spdefense':
    case 'speed':
    case 'total': {
      if (ctx.useBaseStats && ctx.getSpeciesRawBaseStats) {
        const baseA = ctx.getSpeciesRawBaseStats(a.name);
        const baseB = ctx.getSpeciesRawBaseStats(b.name);
        if (key === 'total') {
          valueA = ctx.getSpeciesBaseCombatPower
            ? ctx.getSpeciesBaseCombatPower(a.name)
            : baseA.hp + baseA.attack + baseA.spattack + baseA.defense + baseA.spdefense + baseA.speed;
          valueB = ctx.getSpeciesBaseCombatPower
            ? ctx.getSpeciesBaseCombatPower(b.name)
            : baseB.hp + baseB.attack + baseB.spattack + baseB.defense + baseB.spdefense + baseB.speed;
        } else {
          valueA = baseA[key];
          valueB = baseB[key];
        }
      } else if (key === 'total') {
        valueA = ctx.getCreatureCombatPower(a);
        valueB = ctx.getCreatureCombatPower(b);
      } else if (key === 'hp') {
        valueA = a.maxHp;
        valueB = b.maxHp;
      } else {
        valueA = a[key];
        valueB = b[key];
      }
      break;
    }
    case 'shards':
      valueA = ctx.shards[ctx.getShardKey(a.name, a.rarity)] ?? 0;
      valueB = ctx.shards[ctx.getShardKey(b.name, b.rarity)] ?? 0;
      break;
    case 'shiny':
      valueA = a.isShiny ? 1 : 0;
      valueB = b.isShiny ? 1 : 0;
      break;
    default:
      return 0;
  }

  return compareValues(valueA, valueB, order);
}

export function compareStorageCreaturesMulti(
  a: StorageSortCreature,
  b: StorageSortCreature,
  stack: StorageSortEntry[],
  ctx: StorageSortContext,
): number {
  for (const { key, order } of stack) {
    const cmp = compareStorageCreatures(a, b, key, order, ctx);
    if (cmp !== 0) return cmp;
  }
  return 0;
}

export function sortStorageCreatures<T extends StorageSortCreature>(
  creatures: T[],
  stack: StorageSortEntry[],
  ctx: StorageSortContext,
): T[] {
  if (stack.length === 0) return creatures;
  return creatures.slice().sort((a, b) => compareStorageCreaturesMulti(a, b, stack, ctx));
}

export function getSortButtonClass(
  stack: StorageSortEntry[],
  buttonId: StorageSortKey,
): string {
  let cls = 'sort-btn';
  const entry = stack.find((item) => item.key === buttonId);
  if (entry) {
    cls += ' active';
    if (entry.order === 'asc') cls += ' asc';
  }
  return cls;
}

export function getSortButtonMeta(
  stack: StorageSortEntry[],
  buttonId: StorageSortKey,
): { priority: number; order: StorageSortOrder } | null {
  const idx = stack.findIndex((item) => item.key === buttonId);
  if (idx === -1) return null;
  const entry = stack[idx];
  if (!entry) return null;
  return { priority: idx + 1, order: entry.order };
}

export function getSortButtonPriority(
  stack: StorageSortEntry[],
  buttonId: StorageSortKey,
): number | null {
  return getSortButtonMeta(stack, buttonId)?.priority ?? null;
}

export function getSortButtonOrderSymbol(
  stack: StorageSortEntry[],
  buttonId: StorageSortKey,
): '▲' | '▼' | '' {
  const meta = getSortButtonMeta(stack, buttonId);
  if (!meta) return '';
  return meta.order === 'asc' ? '▲' : '▼';
}

export function sortStackSignature(stack: StorageSortEntry[]): string {
  return stack.map((entry) => `${entry.key}:${entry.order}`).join('|');
}
